        A("cat_instr", "Instrução para a IA (só no modo com chave)", "Instruction for the AI (API-key mode only)", "Instrucción para la IA (solo con clave de API)", "Инструкция для ИИ (только с ключом API)", "Instruction pour l'IA (mode clé API uniquement)", "Anweisung für die KI (nur mit API-Schlüssel)");
        A("cat_gratis", "No modo grátis só as palavras-chave valem. A instrução fica guardada para quando você usar uma chave de API.", "In free mode only the keywords apply. The instruction is kept for when you use an API key.", "En modo gratis solo valen las palabras clave. La instrucción se guarda para cuando uses una clave de API.", "В бесплатном режиме работают только ключевые слова. Инструкция сохранится до использования ключа API.", "En mode gratuit, seuls les mots-clés comptent. L'instruction est conservée pour quand vous utiliserez une clé API.", "Im kostenlosen Modus zählen nur die Schlüsselwörter. Die Anweisung bleibt für einen späteren API-Schlüssel gespeichert.");
        A("cat_criar", "Criar", "Create", "Crear", "Создать", "Créer", "Erstellen");
        A("cat_restaurar", "Restaurar padrão", "Restore default", "Restaurar valores", "Сбросить", "Restaurer par défaut", "Standard wiederherstellen");
        A("cat_apagar", "Apagar categoria", "Delete category", "Borrar categoría", "Удалить категорию", "Supprimer la catégorie", "Kategorie löschen");
        A("cat_apagar_conf", "Clique de novo para apagar", "Click again to delete", "Haz clic de nuevo para borrar", "Нажмите ещё раз для удаления", "Cliquez à nouveau pour supprimer", "Zum Löschen erneut klicken");
        A("cat_reclass", "Reclassificar não travados", "Reclassify unlocked terms", "Reclasificar no bloqueados", "Переклассифицировать незакреплённые", "Reclasser les non verrouillés", "Nicht gesperrte neu einordnen");
        A("cat_reclass_n", "{0} termos mudaram de categoria.", "{0} terms changed category.", "{0} términos cambiaron de categoría.", "Категория изменилась у терминов: {0}.", "{0} termes ont changé de catégorie.", "{0} Begriffe haben die Kategorie gewechselt.");
        A("cat_reclass_ia", "Reclassificar com IA", "Reclassify with AI", "Reclasificar con IA", "Классифицировать с ИИ", "Reclasser avec l'IA", "Mit KI neu einordnen");
        A("cat_reclass_ia_dica", "A IA escolhe a categoria de cada termo não travado do glossário. Gasta tokens uma vez, só quando você aperta. Termos travados não mudam.", "The AI picks the category of each unlocked glossary term. Uses tokens once, only when you press it. Locked terms don't change.", "La IA elige la categoría de cada término no bloqueado del glosario. Gasta tokens una vez, solo cuando lo pulsas. Los términos bloqueados no cambian.", "ИИ выбирает категорию для каждого незакреплённого термина глоссария. Токены тратятся один раз, только по нажатию. Закреплённые термины не меняются.", "L'IA choisit la catégorie de chaque terme non verrouillé du glossaire. Utilise des jetons une fois, seulement quand vous appuyez. Les termes verrouillés ne changent pas.", "Die KI wählt die Kategorie jedes nicht gesperrten Glossarbegriffs. Verbraucht einmal Tokens, nur wenn du drückst. Gesperrte Begriffe ändern sich nicht.");
        A("cia_parar", "Parar", "Stop", "Detener", "Остановить", "Arrêter", "Stoppen");
        A("cia_gratis", "Só no modo com chave.", "Key mode only.", "Solo en el modo con clave.", "Только в режиме с ключом.", "Mode clé uniquement.", "Nur im Schlüssel-Modus.");
        A("cia_nada", "Nenhum termo não travado no glossário.", "No unlocked terms in the glossary.", "Ningún término no bloqueado en el glosario.", "В глоссарии нет незакреплённых терминов.", "Aucun terme non verrouillé dans le glossaire.", "Keine nicht gesperrten Begriffe im Glossar.");
        A("cia_andamento", "Classificando: {0} de {1} (mudaram {2})...", "Classifying: {0} of {1} ({2} changed)...", "Clasificando: {0} de {1} (cambiaron {2})...", "Классификация: {0} из {1} (изменено {2})...", "Classement : {0} sur {1} ({2} modifiés)...", "Einordnen: {0} von {1} ({2} geändert)...");
        A("cia_fim", "Pronto: {0} de {1} termos mudaram de categoria ({2} sem resposta válida).", "Done: {0} of {1} terms changed category ({2} without a valid reply).", "Listo: {0} de {1} términos cambiaron de categoría ({2} sin respuesta válida).", "Готово: {0} из {1} терминов сменили категорию ({2} без корректного ответа).", "Terminé : {0} sur {1} termes ont changé de catégorie ({2} sans réponse valide).", "Fertig: {0} von {1} Begriffen haben die Kategorie gewechselt ({2} ohne gültige Antwort).");
        A("cia_erro", "Erro {0} da IA {1}. Nada mais foi mudado.", "AI error {0} {1}. Nothing else was changed.", "Error {0} de la IA {1}. No se cambió nada más.", "Ошибка ИИ {0} {1}. Больше ничего не изменено.", "Erreur {0} de l'IA {1}. Rien d'autre n'a été modifié.", "KI-Fehler {0} {1}. Sonst wurde nichts geändert.");
        A("cat_limite", "Limite de {0} categorias novas atingido.", "Limit of {0} new categories reached.", "Límite de {0} categorías nuevas alcanzado.", "Достигнут предел: {0} новых категорий.", "Limite de {0} nouvelles catégories atteinte.", "Limit von {0} neuen Kategorien erreicht.");
        A("cat_erro_nome", "Digite um nome que ainda não exista.", "Type a name that does not exist yet.", "Escribe un nombre que no exista.", "Введите имя, которого ещё нет.", "Saisissez un nom qui n'existe pas encore.", "Gib einen Namen ein, den es noch nicht gibt.");
        A("cat_fechar", "Fechar painel", "Close panel", "Cerrar panel", "Закрыть панель", "Fermer le panneau", "Panel schließen");

        // ---- avancado ----
        A("rpm", "Pedidos por minuto", "Requests per minute", "Solicitudes por minuto", "Запросов в минуту", "Requêtes par minute", "Anfragen pro Minute");
        A("lote", "Textos por pedido", "Texts per request", "Textos por solicitud", "Текстов за запрос", "Textes par requête", "Texte pro Anfrage");
        A("rpm_aviso", "Planos grátis de IA têm limite: se aparecer erro 429, diminua os pedidos por minuto.", "Free AI plans have limits: if you see error 429, lower the requests per minute.", "Los planes gratis de IA tienen límite: si aparece el error 429, baja las solicitudes por minuto.", "У бесплатных тарифов ИИ есть лимиты: при ошибке 429 уменьшите число запросов в минуту.", "Les offres gratuites d'IA ont une limite : en cas d'erreur 429, réduisez les requêtes par minute.", "Kostenlose KI-Tarife haben Limits: Bei Fehler 429 die Anfragen pro Minute verringern.");
        A("rpm_gratis", "Modo grátis: ritmo automático. Um pedido por vez; o próximo sai assim que o anterior volta. Se o Google bloquear um endereço, o mod passa para outro sozinho.", "Free mode: automatic pace. One request at a time; the next goes out as soon as the previous one returns. If Google blocks an endpoint, the mod switches to another on its own.", "Modo gratis: ritmo automático. Una solicitud a la vez; la siguiente sale en cuanto vuelve la anterior. Si Google bloquea una dirección, el mod cambia a otra solo.", "Бесплатный режим: темп автоматический. Один запрос за раз; следующий уходит, как только вернулся предыдущий. Если Google заблокирует адрес, мод сам переключится на другой.", "Mode gratuit : rythme automatique. Une requête à la fois ; la suivante part dès que la précédente revient. Si Google bloque une adresse, le mod passe tout seul à une autre.", "Gratis-Modus: automatisches Tempo. Eine Anfrage nach der anderen; die nächste geht raus, sobald die vorige zurück ist. Sperrt Google eine Adresse, wechselt der Mod selbst zu einer anderen.");
        A("botao_canto", " Mostrar o botão 'Tradução' no canto da tela (senão só pela tecla F8)", " Show the 'Translation' button in the screen corner (otherwise F8 only)", " Mostrar el botón 'Traducción' en la esquina (si no, solo con F8)", " Показывать кнопку «Перевод» в углу экрана (иначе только F8)", " Afficher le bouton « Traduction » dans le coin de l'écran (sinon F8 seulement)", " Schaltfläche „Übersetzung“ in der Bildschirmecke anzeigen (sonst nur mit F8)");
        A("limpar_cache", "Limpar cache deste idioma", "Clear cache for this language", "Borrar caché de este idioma", "Очистить кэш этого языка", "Vider le cache de cette langue", "Cache dieser Sprache leeren");
        A("limpar_conf", "Clique de novo para APAGAR o cache", "Click again to DELETE the cache", "Haz clic de nuevo para BORRAR la caché", "Нажмите ещё раз, чтобы УДАЛИТЬ кэш", "Cliquez à nouveau pour SUPPRIMER le cache", "Erneut klicken, um den Cache zu LÖSCHEN");
        A("limpar_aviso", "Isso apaga {0} traduções deste idioma e não tem volta. No modo com chave, traduzir de novo custa de novo. Os termos travados do glossário ficam.", "This deletes {0} translations for this language and cannot be undone. In key mode, translating again costs again. Locked glossary terms are kept.", "Esto borra {0} traducciones de este idioma y no se puede deshacer. En el modo con clave, traducir de nuevo vuelve a costar. Los términos bloqueados del glosario se mantienen.", "Будет удалено {0} переводов этого языка без возможности отмены. В режиме с ключом повторный перевод снова стоит денег. Закреплённые термины глоссария сохранятся.", "Cela supprime {0} traductions de cette langue, sans retour possible. En mode clé, retraduire coûte à nouveau. Les termes verrouillés du glossaire sont conservés.", "Das löscht {0} Übersetzungen dieser Sprache und kann nicht rückgängig gemacht werden. Im Schlüssel-Modus kostet erneutes Übersetzen wieder. Gesperrte Glossarbegriffe bleiben erhalten.");
        A("limpar_feito", "Cache apagado. O texto na tela será traduzido de novo.", "Cache deleted. On-screen text will be translated again.", "Caché borrada. El texto en pantalla se traducirá de nuevo.", "Кэш удалён. Текст на экране будет переведён заново.", "Cache supprimé. Le texte à l'écran sera retraduit.", "Cache gelöscht. Der Text auf dem Bildschirm wird neu übersetzt.");
        A("contexto", " Mandar as últimas frases como contexto para a IA (diálogos mais coerentes)", " Send the last lines as context to the AI (more consistent dialogue)", " Enviar las últimas frases como contexto a la IA (diálogos más coherentes)", " Отправлять ИИ последние фразы как контекст (более связные диалоги)", " Envoyer les dernières phrases comme contexte à l'IA (dialogues plus cohérents)", " Letzte Sätze als Kontext an die KI senden (stimmigere Dialoge)");
        A("contexto_dica", "Só no modo com chave. Gasta um pouco mais de tokens por pedido.", "Key mode only. Uses a few more tokens per request.", "Solo en el modo con clave. Gasta algunos tokens más por solicitud.", "Только в режиме с ключом. Немного больше токенов на запрос.", "Mode clé uniquement. Utilise un peu plus de jetons par requête.", "Nur im Schlüssel-Modus. Etwas mehr Tokens pro Anfrage.");
        A("fonte_min", "Fonte mínima quando o texto não cabe", "Minimum font size when text doesn't fit", "Fuente mínima cuando el texto no cabe", "Мин. шрифт, если текст не помещается", "Police minimale si le texte ne rentre pas", "Mindestschrift, wenn der Text nicht passt");
        A("fonte_min_dica", "Porcentagem do tamanho original. Menor = cabe mais texto (bom para alemão, russo...), mas fica menor. Vale para os próximos textos ajustados.", "Percent of the original size. Lower = more text fits (good for German, Russian...), but smaller. Applies to texts adjusted from now on.", "Porcentaje del tamaño original. Menor = cabe más texto (bueno para alemán, ruso...), pero más pequeño. Vale para los próximos textos ajustados.", "Процент от исходного размера. Меньше = больше текста помещается (хорошо для немецкого, русского...), но мельче. Для текстов, подгоняемых с этого момента.", "Pourcentage de la taille d'origine. Plus bas = plus de texte rentre (utile pour l'allemand, le russe...), mais plus petit. S'applique aux prochains textes ajustés.", "Prozent der Originalgröße. Niedriger = mehr Text passt (gut für Deutsch, Russisch...), aber kleiner. Gilt für ab jetzt angepasste Texte.");
        A("fonte_original", "Original do jogo", "Game's original", "Original del juego", "Оригинал игры", "Celle du jeu", "Original des Spiels");
        A("fonte_trad_dica", "Troca a fonte só dos textos traduzidos. Aparecem só as {0} fontes que têm todas as letras do idioma escolhido.", "Changes the font of translated texts only. Only the {0} fonts that have every letter of the chosen language are listed.", "Cambia la fuente solo de los textos traducidos. Solo aparecen las {0} fuentes que tienen todas las letras del idioma elegido.", "Меняет шрифт только у переведённых текстов. Показаны только {0} шрифтов, в которых есть все буквы выбранного языка.", "Change la police des textes traduits uniquement. Seules les {0} polices qui ont toutes les lettres de la langue choisie sont listées.", "Ändert nur die Schrift übersetzter Texte. Es werden nur die {0} Schriften gezeigt, die alle Buchstaben der gewählten Sprache haben.");
        A("nav_fontes", "Fontes", "Fonts", "Fuentes", "Шрифты", "Polices", "Schriften");
        A("fonte_pasta_dica", "Coloque um .ttf ou .otf na pasta de fontes e clique em Atualizar lista para ele aparecer aqui.", "Put a .ttf or .otf in the fonts folder and click Refresh list to see it here.", "Pon un .ttf u .otf en la carpeta de fuentes y pulsa Actualizar lista para verlo aquí.", "Положите .ttf или .otf в папку шрифтов и нажмите «Обновить список».", "Mettez un .ttf ou .otf dans le dossier des polices et cliquez sur Actualiser la liste.", "Lege eine .ttf oder .otf in den Schriftordner und klicke auf Liste aktualisieren.");
        A("fonte_pasta", "Pasta de fontes", "Fonts folder", "Carpeta de fuentes", "Папка шрифтов", "Dossier des polices", "Schriftordner");
        A("fonte_atualizar", "Atualizar lista", "Refresh list", "Actualizar lista", "Обновить список", "Actualiser la liste", "Liste aktualisieren");
        A("raciocinio", "IA pensa antes de traduzir", "AI thinks before translating", "La IA piensa antes de traducir", "ИИ думает перед переводом", "L'IA réfléchit avant de traduire", "KI denkt vor dem Übersetzen nach");
        A("raciocinio_dica", "Só no modo com chave. Ligado: o modelo pensa o quanto quiser (pode traduzir melhor, mas fica bem mais lento). Desligado: pede o mínimo de raciocínio (mais rápido).", "Key mode only. On: the model thinks as much as it wants (may translate better, but much slower). Off: asks for minimal reasoning (faster).", "Solo en el modo con clave. Activado: el modelo piensa lo que quiera (puede traducir mejor, pero mucho más lento). Desactivado: pide el mínimo razonamiento (más rápido).", "Только в режиме с ключом. Вкл.: модель думает сколько хочет (может переводить лучше, но гораздо медленнее). Выкл.: минимум рассуждений (быстрее).", "Mode clé uniquement. Activé : le modèle réfléchit autant qu'il veut (peut mieux traduire, mais beaucoup plus lent). Désactivé : raisonnement minimal (plus rapide).", "Nur im Schlüssel-Modus. An: das Modell denkt so viel es will (kann besser übersetzen, aber viel langsamer). Aus: minimales Reasoning (schneller).");
        A("pre_trad", "Pré-traduzir textos já carregados (inclusive menus escondidos)", "Pre-translate loaded texts (including hidden menus)", "Pretraducir textos ya cargados (incluso menús ocultos)", "Заранее перевести загруженные тексты (включая скрытые меню)", "Pré-traduire les textes chargés (y compris les menus cachés)", "Geladene Texte vorab übersetzen (auch versteckte Menüs)");
        A("pre_dica", "Põe na fila tudo o que o jogo já carregou. Quando a janela abrir, o texto já vem traduzido do cache.", "Queues everything the game has already loaded. When the window opens, the text already comes translated from the cache.", "Pone en la cola todo lo que el juego ya cargó. Cuando se abra la ventana, el texto ya viene traducido de la caché.", "Ставит в очередь всё, что игра уже загрузила. Когда окно откроется, текст уже будет переведён из кэша.", "Met en file tout ce que le jeu a déjà chargé. Quand la fenêtre s'ouvre, le texte vient déjà traduit du cache.", "Stellt alles, was das Spiel geladen hat, in die Warteschlange. Öffnet sich das Fenster, kommt der Text schon übersetzt aus dem Cache.");
        A("pre_dica_gratis", "Põe na fila tudo o que o jogo já carregou. No modo grátis pode demorar vários minutos (o Google limita os pedidos).", "Queues everything the game has already loaded. In free mode this can take several minutes (Google limits requests).", "Pone en la cola todo lo que el juego ya cargó. En el modo gratis puede tardar varios minutos (Google limita las solicitudes).", "Ставит в очередь всё, что игра уже загрузила. В бесплатном режиме это может занять несколько минут (Google ограничивает запросы).", "Met en file tout ce que le jeu a déjà chargé. En mode gratuit, cela peut prendre plusieurs minutes (Google limite les requêtes).", "Stellt alles, was das Spiel geladen hat, in die Warteschlange. Im Gratis-Modus kann das mehrere Minuten dauern (Google begrenzt Anfragen).");
        A("pre_pausado", "Aperte \"Começar tradução\" primeiro.", "Press \"Start translating\" first.", "Pulsa \"Empezar traducción\" primero.", "Сначала нажмите «Начать перевод».", "Appuyez d'abord sur « Démarrer la traduction ».", "Drücke zuerst „Übersetzung starten“.");
        A("pre_ok", "{0} textos novos na fila.", "{0} new texts queued.", "{0} textos nuevos en la cola.", "В очереди {0} новых текстов.", "{0} nouveaux textes en file.", "{0} neue Texte in der Warteschlange.");
        A("comp_exportar", "Exportar glossário e cache", "Export glossary and cache", "Exportar glosario y caché", "Экспорт глоссария и кэша", "Exporter glossaire et cache", "Glossar und Cache exportieren");
        A("comp_importar", "Importar", "Import", "Importar", "Импорт", "Importer", "Importieren");
        A("comp_dica", "Pasta \"compartilhar\": glossario_{0}.txt e cache_{0}.txt. Para importar a tradução de um amigo, coloque os arquivos dele nessa pasta. Importar só acrescenta o que falta, nada seu é trocado.", "\"compartilhar\" folder: glossario_{0}.txt and cache_{0}.txt. To import a friend's translation, put their files in that folder. Import only adds what is missing; nothing of yours is replaced.", "Carpeta \"compartilhar\": glossario_{0}.txt y cache_{0}.txt. Para importar la traducción de un amigo, pon sus archivos en esa carpeta. Importar solo añade lo que falta; nada tuyo se reemplaza.", "Папка «compartilhar»: glossario_{0}.txt и cache_{0}.txt. Чтобы импортировать перевод друга, положите его файлы в эту папку. Импорт только добавляет недостающее, ваше не заменяется.", "Dossier « compartilhar » : glossario_{0}.txt et cache_{0}.txt. Pour importer la traduction d'un ami, placez ses fichiers dans ce dossier. L'import ajoute seulement ce qui manque ; rien du vôtre n'est remplacé.", "Ordner „compartilhar“: glossario_{0}.txt und cache_{0}.txt. Um die Übersetzung eines Freundes zu importieren, lege seine Dateien in diesen Ordner. Import fügt nur Fehlendes hinzu, nichts von dir wird ersetzt.");
        A("comp_exportado", "Exportado: {0} termos do glossário e {1} traduções do cache.", "Exported: {0} glossary terms and {1} cache translations.", "Exportado: {0} términos del glosario y {1} traducciones de la caché.", "Экспортировано: {0} терминов глоссария и {1} переводов кэша.", "Exporté : {0} termes du glossaire et {1} traductions du cache.", "Exportiert: {0} Glossarbegriffe und {1} Cache-Übersetzungen.");
        A("comp_importado", "Importado: {0} termos novos no glossário e {1} traduções novas no cache.", "Imported: {0} new glossary terms and {1} new cache translations.", "Importado: {0} términos nuevos en el glosario y {1} traducciones nuevas en la caché.", "Импортировано: {0} новых терминов глоссария и {1} новых переводов кэша.", "Importé : {0} nouveaux termes du glossaire et {1} nouvelles traductions du cache.", "Importiert: {0} neue Glossarbegriffe und {1} neue Cache-Übersetzungen.");
        A("comp_nada", "Nenhum arquivo deste idioma ({0}) na pasta \"compartilhar\".", "No file for this language ({0}) in the \"compartilhar\" folder.", "Ningún archivo de este idioma ({0}) en la carpeta \"compartilhar\".", "В папке «compartilhar» нет файлов для этого языка ({0}).", "Aucun fichier de cette langue ({0}) dans le dossier « compartilhar ».", "Keine Datei für diese Sprache ({0}) im Ordner „compartilhar“.");
        A("comp_erro", "Erro: {0}", "Error: {0}", "Error: {0}", "Ошибка: {0}", "Erreur : {0}", "Fehler: {0}");
        A("status", "Na fila: {0}   |   Traduzidos agora: {1}   |   No cache: {2}   |   Pedidos: {3}   |   Erros: {4}", "Queue: {0}   |   Translated now: {1}   |   In cache: {2}   |   Requests: {3}   |   Errors: {4}", "En cola: {0}   |   Traducidos ahora: {1}   |   En caché: {2}   |   Solicitudes: {3}   |   Errores: {4}", "В очереди: {0}   |   Переведено: {1}   |   В кэше: {2}   |   Запросов: {3}   |   Ошибок: {4}", "En file : {0}   |   Traduits : {1}   |   En cache : {2}   |   Requêtes : {3}   |   Erreurs : {4}", "Warteschlange: {0}   |   Übersetzt: {1}   |   Im Cache: {2}   |   Anfragen: {3}   |   Fehler: {4}");
        A("ultimo_erro", "Último erro: ", "Last error: ", "Último error: ", "Последняя ошибка: ", "Dernière erreur : ", "Letzter Fehler: ");
        A("aviso_teclas", "Abra este menu no menu inicial ou na pausa: as teclas digitadas aqui também chegam ao jogo. A API key fica salva só no seu PC (pasta TraducaoLive).", "Open this menu on the main menu or while paused: keys typed here also reach the game. The API key is stored only on your PC (TraducaoLive folder).", "Abre este menú en el menú inicial o en pausa: las teclas que escribas aquí también llegan al juego. La clave de API se guarda solo en tu PC (carpeta TraducaoLive).", "Открывайте это меню в главном меню или на паузе: нажатия клавиш здесь доходят и до игры. Ключ API хранится только на вашем ПК (папка TraducaoLive).", "Ouvrez ce menu dans le menu principal ou en pause : les touches saisies ici arrivent aussi dans le jeu. La clé API n'est enregistrée que sur votre PC (dossier TraducaoLive).", "Öffne dieses Menü im Hauptmenü oder in der Pause: Hier getippte Tasten erreichen auch das Spiel. Der API-Schlüssel wird nur auf deinem PC gespeichert (Ordner TraducaoLive).");

        // ---- erros e teste (Motor) ----
        A("e_chave", "chave recusada ({0}). Confira a API key.", "key rejected ({0}). Check the API key.", "clave rechazada ({0}). Revisa la clave de API.", "ключ отклонён ({0}). Проверьте ключ API.", "clé refusée ({0}). Vérifiez la clé API.", "Schlüssel abgelehnt ({0}). Prüfe den API-Schlüssel.");
        A("e_404", "não encontrado (404). Confira a URL e o nome do modelo.", "not found (404). Check the URL and the model name.", "no encontrado (404). Revisa la URL y el nombre del modelo.", "не найдено (404). Проверьте URL и название модели.", "introuvable (404). Vérifiez l'URL et le nom du modèle.", "nicht gefunden (404). Prüfe URL und Modellname.");
        A("e_429", "limite de uso atingido (429). Diminua os pedidos por minuto.", "usage limit reached (429). Lower the requests per minute.", "límite de uso alcanzado (429). Baja las solicitudes por minuto.", "лимит исчерпан (429). Уменьшите число запросов в минуту.", "limite d'utilisation atteinte (429). Réduisez les requêtes par minute.", "Nutzungslimit erreicht (429). Verringere die Anfragen pro Minute.");
        A("e_erro", "erro {0}{1}", "error {0}{1}", "error {0}{1}", "ошибка {0}{1}", "erreur {0}{1}", "Fehler {0}{1}");
        A("e_formato", "a IA respondeu fora do formato (tentando um texto por vez)", "the AI replied in the wrong format (trying one text at a time)", "la IA respondió fuera de formato (probando un texto a la vez)", "ИИ ответил не в том формате (пробую по одному тексту)", "l'IA a répondu hors format (essai un texte à la fois)", "Die KI antwortete im falschen Format (versuche einen Text nach dem anderen)");
        A("t_testando", "testando...", "testing...", "probando...", "проверка...", "test en cours...", "teste...");
        A("t_nao_deu", "não deu: {0}", "failed: {0}", "no funcionó: {0}", "не удалось: {0}", "échec : {0}", "fehlgeschlagen: {0}");
        A("t_erro", "erro: {0}", "error: {0}", "error: {0}", "ошибка: {0}", "erreur : {0}", "Fehler: {0}");
        A("t_formato", "respondeu, mas fora do formato esperado", "replied, but not in the expected format", "respondió, pero fuera del formato esperado", "ответил, но не в ожидаемом формате", "a répondu, mais hors du format attendu", "antwortete, aber nicht im erwarteten Format");
        A("t_chave", "chave recusada ({0})", "key rejected ({0})", "clave rechazada ({0})", "ключ отклонён ({0})", "clé refusée ({0})", "Schlüssel abgelehnt ({0})");
        A("t_404", "404: confira a URL e o modelo", "404: check the URL and the model", "404: revisa la URL y el modelo", "404: проверьте URL и модель", "404 : vérifiez l'URL et le modèle", "404: prüfe URL und Modell");
